/**
 * S0.8 — AoI cell-grid micro-benchmark (THROWAWAY spike tooling).
 *
 * Run:  node tools/spikes/s0.8/bench.mjs
 * Out:  tools/spikes/s0.8/report.json (regenerated by every run)
 *
 * Measures the full rebuild tick of the aoi.ts cell grid (the algorithm spec
 * for the Phase-5 Go port) across presence counts x cell sizes x population
 * distributions. MEASURED TICK COST ONLY — no capacity figure anywhere in
 * this report is extrapolated (ROADMAP.md §3.4 / §1.3).
 */
import { performance } from 'node:perf_hooks';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { AoiGrid } from './aoi.ts';

const DATE = '2026-09-06';

// ---- benchmark parameters (fixed by the S0.8 task brief) ------------------
const AREA_METRES = 5000; // synthetic region: 5 x 5 km (25e6 m^2)
const AOI_RADIUS = 500; // fixed so CELL SIZE is the only grid variable
const CELL_SIZES = [100, 250, 500, 1000]; // m
const COUNTS = [100, 500, 1000, 5000]; // synthetic presences
const DISTRIBUTIONS = ['uniform', 'clustered'];
const WARMUP_TICKS = 30;
const MEASURED_TICKS = 300;
const TICK_HZ = 20; // INPUT assumption from the S0.8 brief (Nakama MatchInit allows 1-60)
const WALK_SPEED_MPS = 1.4; // step = 0.07 m/tick at 20 Hz
const SEED = 20260906;

// Population distribution: clustered = Stone-Town-like dense centre.
const HOTSPOT_AREA_FRACTION = 0.1; // 10% of the area
const HOTSPOT_SHARE = 0.8; // holds 80% of the presences (in expectation)
const HOTSPOT_SIDE = Math.sqrt(HOTSPOT_AREA_FRACTION) * AREA_METRES; // 1581.1388... m

// ---- 1500 B wire model (DERIVATION INPUT, not a measurement) --------------
// The byte ledger per opcode is owned by the Phase-5 netcode design doc
// (NETWORKING.md §4); until that doc exists these field budgets are the
// stated model this derivation runs on, chosen to be typical of the compact
// state NETWORKING.md §8 requires (frame ID, movement regime, model revision).
const MSG_CAP_BYTES = 1500; // NETWORKING.md §4 hard rule (CLAUDE.md invariant)
const ENVELOPE_BYTES = 16; // opcode 2 + tick 4 + entityCount 2 + flags 2 + reserved 6
const FULL_RECORD_BYTES = 24; // id 4 + pos 2xf32 8 + vel 2xi16 4 + heading u16 2 + frame 1 + regime 1 + revision u16 2 + flags u16 2
const DELTA_RECORD_BYTES = 10; // idDelta 2 + pos 2xf32 8

// ---- helpers ---------------------------------------------------------------
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Nearest-rank percentile on an ascending-sorted array. */
function percentile(sorted, q) {
  const n = sorted.length;
  const idx = Math.min(n - 1, Math.max(0, Math.ceil(q * n) - 1));
  return sorted[idx];
}

function mean(arr) {
  let s = 0;
  for (let i = 0; i < arr.length; i++) s += arr[i];
  return s / arr.length;
}

function place(count, distribution, rng) {
  const xs = new Float64Array(count);
  const zs = new Float64Array(count);
  const centre = AREA_METRES / 2;
  for (let i = 0; i < count; i++) {
    if (distribution === 'clustered' && rng() < HOTSPOT_SHARE) {
      xs[i] = centre + (rng() - 0.5) * HOTSPOT_SIDE;
      zs[i] = centre + (rng() - 0.5) * HOTSPOT_SIDE;
    } else {
      xs[i] = rng() * AREA_METRES;
      zs[i] = rng() * AREA_METRES;
    }
  }
  return { xs, zs };
}

// ---- one config -------------------------------------------------------------
function runConfig(count, cellSize, distribution, distIndex) {
  const seed = (SEED ^ Math.imul(cellSize, 0x9e3779b1) ^ Math.imul(count, 0x85ebca77) ^ Math.imul(distIndex + 1, 0xc2b2ae3d)) >>> 0;
  const rng = mulberry32(seed);
  const grid = new AoiGrid({ cellSize, aoiRadius: AOI_RADIUS });
  const { xs, zs } = place(count, distribution, rng);
  const step = WALK_SPEED_MPS / TICK_HZ;
  for (let i = 0; i < count; i++) grid.add(i + 1, xs[i], zs[i]);

  const tickSamples = new Float64Array(MEASURED_TICKS);
  const moveSamples = new Float64Array(MEASURED_TICKS);
  const rebuildSamples = new Float64Array(MEASURED_TICKS);
  let maxCellPop = 0;
  let maxInterest = 0;
  let interestSumPerTick = 0;
  let interestTicks = 0;

  for (let t = 0; t < WARMUP_TICKS + MEASURED_TICKS; t++) {
    const measured = t >= WARMUP_TICKS;
    const t0 = measured ? performance.now() : 0;
    // Phase 1 — move: every presence steps once, through the grid API.
    for (let i = 0; i < count; i++) {
      const ang = rng() * 2 * Math.PI;
      let x = xs[i] + Math.cos(ang) * step;
      let z = zs[i] + Math.sin(ang) * step;
      if (x < 0) x = -x;
      else if (x > AREA_METRES) x = 2 * AREA_METRES - x;
      if (z < 0) z = -z;
      else if (z > AREA_METRES) z = 2 * AREA_METRES - z;
      xs[i] = x;
      zs[i] = z;
      grid.move(i + 1, x, z);
    }
    // Phase 2 — full interest rebuild for every presence.
    const t1 = measured ? performance.now() : 0; // between the phases
    const interests = grid.rebuildTick();
    const t2 = measured ? performance.now() : 0;
    if (measured) {
      const k = t - WARMUP_TICKS;
      moveSamples[k] = t1 - t0;
      rebuildSamples[k] = t2 - t1;
      tickSamples[k] = t2 - t0;
    }
    // Untimed stats pass: extremes over the whole measured run.
    const mp = grid.maxCellPopulation();
    if (mp.population > maxCellPop) maxCellPop = mp.population;
    let sumLen = 0;
    let maxLen = 0;
    interests.forEach((buf) => {
      const n = buf.length;
      sumLen += n;
      if (n > maxLen) maxLen = n;
    });
    if (maxLen > maxInterest) maxInterest = maxLen;
    interestSumPerTick += sumLen;
    interestTicks++;
  }

  const sortedTicks = Float64Array.from(tickSamples).sort();
  const finalPops = [...grid.populations().values()].sort((a, b) => a - b);
  // Sample the AoI cell-set size once at the end (stats only, never per tick).
  const sampleN = Math.min(count, 500);
  const stride = Math.max(1, Math.floor(count / sampleN));
  let aoiCellsSum = 0;
  let aoiCellsN = 0;
  for (let id = 1; id <= count; id += stride) {
    aoiCellsSum += grid.aoiCellCount(id);
    aoiCellsN++;
  }

  const maxTickMs = sortedTicks[MEASURED_TICKS - 1];
  const derivedFullStateBytesAtMax = ENVELOPE_BYTES + FULL_RECORD_BYTES * maxInterest;
  return {
    id: `N${count}-cs${cellSize}-${distribution}`,
    count,
    cellSize,
    distribution,
    aoiRadius: AOI_RADIUS,
    meanTickMs: mean(sortedTicks),
    p50TickMs: percentile(sortedTicks, 0.5),
    p99TickMs: percentile(sortedTicks, 0.99),
    maxTickMs,
    meanMovePhaseMs: mean(moveSamples),
    meanRebuildPhaseMs: mean(rebuildSamples),
    meanTickUsPerPresence: (mean(sortedTicks) * 1000) / count, // derived normalization of two measured rows
    cellCount: grid.cellCount(),
    maxCellPopulation: maxCellPop, // max over the 300 measured ticks
    finalCellPopulationP50: percentile(finalPops, 0.5),
    finalCellPopulationP90: percentile(finalPops, 0.9),
    finalCellPopulationMax: finalPops[finalPops.length - 1],
    maxInterestPopulation: maxInterest, // max, over measured ticks, of one observer's AoI set
    meanInterestPopulation: interestSumPerTick / (interestTicks * count),
    meanAoiCellCount: aoiCellsSum / aoiCellsN,
    derivedFullStateMessageBytesAtMax: derivedFullStateBytesAtMax,
    fullStateViolates1500B: derivedFullStateBytesAtMax > MSG_CAP_BYTES,
    maxInterestExceedsDeltaCap: maxInterest > Math.floor((MSG_CAP_BYTES - ENVELOPE_BYTES) / DELTA_RECORD_BYTES),
  };
}

// ---- run the grid ------------------------------------------------------------
const configs = [];
for (let d = 0; d < DISTRIBUTIONS.length; d++) {
  const distribution = DISTRIBUTIONS[d];
  for (const count of COUNTS) {
    for (const cellSize of CELL_SIZES) {
      process.stdout.write(`running ${`N${count}-cs${cellSize}-${distribution}`} ...\n`);
      configs.push(runConfig(count, cellSize, distribution, d));
    }
  }
}

// ---- derivation: 1500 B rule vs measured populations -------------------------
const fullStateCapPopulation = Math.floor((MSG_CAP_BYTES - ENVELOPE_BYTES) / FULL_RECORD_BYTES); // 61
const deltaCapPopulation = Math.floor((MSG_CAP_BYTES - ENVELOPE_BYTES) / DELTA_RECORD_BYTES); // 148
const fullStateAtCapBytes = ENVELOPE_BYTES + FULL_RECORD_BYTES * fullStateCapPopulation;
const fullStateAtCapPerSecKB = (fullStateAtCapBytes * TICK_HZ) / 1000;

const worst = configs.reduce((a, b) => (b.maxInterestPopulation > a.maxInterestPopulation ? b : a));
const chosen = null; // adopted cell size is decided in ADR-009 from these rows; report.json stays decision-free

const report = {
  spike: 'S0.8 — AoI cell-grid micro-benchmark (cell grid per ARCHITECTURE.md §6; rebuild-subscriptions-per-tick semantics; benchmark doubles as the algorithm spec for the Phase-5 Go port)',
  date: DATE,
  host: 'Windows 11 dev box (Ryzen 7 7445HS, RTX 4050 Laptop, 15.2 GB RAM), Node single process',
  toolVersions: {
    node: process.version,
    typescript: '7.0.2 (dev tooling, caret-pinned; spike files are excluded from the repo typecheck program per CLAUDE.md carve-out)',
    vitest: '5.0.0 (dev tooling, caret-pinned)',
  },
  repro: 'node tools/spikes/s0.8/bench.mjs — placement and movement RNG fully seeded (mulberry32, per-config derived seed); timing rows vary run to run by their nature. Correctness of the algorithm under test: npx vitest run tools/spikes/s0.8',
  method: {
    grid: 'tools/spikes/s0.8/aoi.ts is both the benchmark implementation and the normative algorithm spec for the Phase-5 Go port (ARCHITECTURE.md §6: "per tick, the runtime computes each client\'s area of interest as a set of cells (own cell + radius)"; NETWORKING.md §5/§9). Static square grid, cell = (floor(x/cs), floor(z/cs)); membership = one long-lived member array per cell, swap-remove is O(cell population), emptied cells pruned; per tick, REBUILD semantics (no incremental diff): every presence is an observer, its AoI is the set of cells whose closed rectangle intersects the 500 m disc around it (nearest-point/clamp test, f64), candidate cell range padded one ring beyond the raw floor bounds so exact tangency and f64 rounding survive (the rect test is the authority); interest set = member ids of those cells minus the observer; interest buffers reused across ticks so a rebuild tick allocates nothing.',
    bench: 'perf_hooks performance.now() around two per-tick phases: (1) move phase — every presence takes one random-direction step of 0.07 m (1.4 m/s walk at the assumed 20 Hz tick rate) with reflection at the 5x5 km boundary, applied through grid.move(); the span includes one mulberry32 call per presence, which bounds the AoI-independent floor of the tick cost; (2) rebuild phase — one grid.rebuildTick() rebuilding every presence\'s interest set from scratch. Headline "full rebuild tick" = move + rebuild spans together (mean/p50/p99/max over 300 measured ticks after 30 warmup ticks; p99 is the 297th of 300 sorted samples, nearest-rank). Per-tick stats passes (max cell population, interest-set sizes) run OUTSIDE the timed spans. Configs run sequentially in one process; GC pauses inside the measured window are included by design — managed-runtime honesty, and one reason the Node numbers are not Go numbers.',
    distributions: {
      uniform: 'x,z ~ U(0, 5000) independently over the 5x5 km area (density N / 25e6 m^2).',
      clustered: 'Stone-Town-like dense centre: 80% of presences uniform in the centred square of side sqrt(0.10)*5000 = 1581.1388 m (area 2.5e6 m^2 = 10% of the area), remaining 20% uniform over the full area; expected hotspot density 0.8N / 2.5e6 m^2.',
    },
    interestMetrics: 'maxCellPopulation = max over the 300 measured ticks of the largest cell member array (per-tick scan outside the timed spans); finalCellPopulationP50/P90/Max = nearest-rank percentiles of the cell-population snapshot at the final tick; maxInterestPopulation = max over measured ticks of any single observer\'s rebuilt interest set (the driver of the coalesced per-presence broadcast size); meanInterestPopulation = mean per observer; meanAoiCellCount = mean size of the AoI CELL set over a <=500-presence sample at the final tick (geometry of the rect-intersect-disc rule).',
    messageSize: 'DERIVATION, clearly not a measurement: the measured populations are combined with the NETWORKING.md §4 hard cap (<=1500 B per message, ~1 message per tick per presence — the coalesced per-presence broadcast framing) and a STATED wire model (field ledger below) that the Phase-5 netcode design doc must replace with its own byte ledger. A per-cell broadcast framing is noted for contrast: it would emit meanAoiCellCount messages per presence per tick, violating the one-message rule outright.',
  },
  parameters: {
    areaMetres: AREA_METRES,
    aoiRadiusMetres: AOI_RADIUS,
    cellSizes: CELL_SIZES,
    counts: COUNTS,
    distributions: DISTRIBUTIONS,
    warmupTicks: WARMUP_TICKS,
    measuredTicks: MEASURED_TICKS,
    tickHz: TICK_HZ,
    tickHzProvenance: 'INPUT assumption from the S0.8 task brief, not a measurement; Nakama MatchInit permits tickrate 1-60 [EXTERNAL https://heroiclabs.com/docs/nakama/server-framework/go-runtime/function-reference/match-handler/]',
    walkSpeedMps: WALK_SPEED_MPS,
    stepMetresPerTick: WALK_SPEED_MPS / TICK_HZ,
    seed: SEED,
    hotspotAreaFraction: HOTSPOT_AREA_FRACTION,
    hotspotShare: HOTSPOT_SHARE,
    hotspotSideMetres: HOTSPOT_SIDE,
  },
  wireModel: {
    status: 'DERIVATION INPUT — the per-opcode byte ledger is owned by the Phase-5 netcode design doc (NETWORKING.md §4); these budgets stand in until that doc exists.',
    messageCapBytes: MSG_CAP_BYTES,
    envelopeBytes: ENVELOPE_BYTES,
    fullStateRecordBytes: FULL_RECORD_BYTES,
    fullStateRecordLedger: 'compact id u32 4 + position 2xf32 8 + velocity 2xi16 4 + heading u16 2 + frameId u8 1 + movementRegime u8 1 + modelRevision u16 2 + stateFlags u16 2 = 24 (compact state per NETWORKING.md §8 includes frame ID, movement regime, model revision)',
    deltaRecordBytes: DELTA_RECORD_BYTES,
    deltaRecordLedger: 'idDelta u16 2 + position 2xf32 8 = 10 (velocity/heading/regime/revision omitted unless changed)',
  },
  derivation: {
    framing: 'Coalesced per-presence broadcast (NETWORKING.md §4 rule 2): one message per tick per presence containing the state of that presence\'s rebuilt interest set (its AoI neighbor set). Message bytes = envelopeBytes + recordBytes * interestPopulation.',
    fullStateCapPopulation, // 61
    fullStateCapFormula: 'floor((1500 - 16) / 24) = 61 presences in the AoI before a FULL-state per-tick broadcast violates the 1500 B cap',
    deltaCapPopulation, // 148
    deltaCapFormula: 'floor((1500 - 16) / 10) = 148 presences in the AoI before even the 10 B delta-record path violates the cap — beyond it the remaining lever is the NETWORKING.md §9 priority tiers (full-rate local cell / interpolated adjacent / throttled beyond), because the cap never moves',
    fullStateLegalMessageBytesAtCap: fullStateAtCapBytes, // 1480
    fullStateAtCapPerSecKB, // derived at the assumed 20 Hz: 29.6 kB/s ≈ 0.24 Mbps per client — the per-message cap binds long before any per-second budget
    fullStateAtCapPerSecProvenance: 'DERIVED: 1480 B * 20 Hz = 29.6 kB/s; the 5-10 Mbps access envelope it must fit is B-RTT-09, an ASSUMPTION under test [PLACEHOLDER — gate: S0.9]',
    worstConfig: worst.id,
    worstMaxInterestPopulation: worst.maxInterestPopulation,
    worstFullStateMessageBytes: worst.derivedFullStateMessageBytesAtMax,
    worstOverFullStateCapFactor: worst.maxInterestPopulation / fullStateCapPopulation,
    worstOverDeltaCapFactor: worst.maxInterestPopulation / deltaCapPopulation,
  },
  configs,
  chosenCellSizeAdr: chosen,
  noExtrapolation: 'Measured tick cost and measured populations ONLY. No player-capacity figure, no "supports N players", and no per-presence linear extrapolation beyond the measured counts is licensed by this report (ROADMAP.md §3.4 and §1.3). meanTickUsPerPresence is a normalization of two measured rows, not a unit cost.',
  process: { rssAfterRunMiB: Math.round(process.memoryUsage().rss / 1048576) },
};

const outPath = join(dirname(fileURLToPath(import.meta.url)), 'report.json');
writeFileSync(outPath, JSON.stringify(report, null, 2) + '\n');
process.stdout.write(`wrote ${outPath}\n`);
